import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJFGRv8Z.js";var i=JSON.parse(`{"title":"Docker 部署","description":"","frontmatter":{},"headers":[],"relativePath":"operations/deployment.md","filePath":"operations/deployment.md","lastUpdated":1788621106000}`),a={name:`operations/deployment.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="docker-部署" tabindex="-1">Docker 部署 <a class="header-anchor" href="#docker-部署" aria-label="Permalink to “Docker 部署”">​</a></h1><p>本文面向自行部署草丛 Mail 的维护者。本文档仓库只保存公开说明；应用代码、生产环境文件、数据库、邮件数据和私钥应按各自发布与备份策略管理。</p><h2 id="服务组成" tabindex="-1">服务组成 <a class="header-anchor" href="#服务组成" aria-label="Permalink to “服务组成”">​</a></h2><table tabindex="0"><thead><tr><th>服务</th><th>用途</th><th>持久化</th></tr></thead><tbody><tr><td><code>db</code></td><td>PostgreSQL 业务数据</td><td><code>postgres_data</code></td></tr><tr><td><code>redis</code></td><td>缓存、限流和一次性流程证明</td><td><code>redis_data</code></td></tr><tr><td><code>rspamd</code></td><td>入站反垃圾评分</td><td><code>rspamd_data</code></td></tr><tr><td><code>backend</code></td><td>Web API、SMTP、IMAP、POP3、迁移和后台任务</td><td><code>mail_storage</code>、<code>uploads_data</code></td></tr><tr><td><code>frontend</code></td><td><code>/app/</code> 邮箱应用</td><td>镜像内静态文件</td></tr><tr><td><code>website</code></td><td>站点根路径官网</td><td>镜像内静态文件</td></tr><tr><td><code>nginx</code></td><td>同域路由、静态缓存和可信代理边界</td><td>配置挂载</td></tr></tbody></table><p>容器可以重建，PostgreSQL、邮件存储、上传文件、环境配置和 TLS 私钥不能跟随容器删除。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to “前置条件”">​</a></h2><ul><li>受支持的 Linux 主机。</li><li>从可信软件源安装的 Docker Engine、Compose 插件和 Git。</li><li>可设置 A/AAAA、MX、TXT 与 PTR/rDNS 的域名。</li><li>允许 Web、SMTP 入站、SMTP Submission、IMAPS 和 POP3S 所需端口。</li><li>PostgreSQL 与邮件卷的持久化磁盘、监控和异机备份。</li></ul><p>不要把网络下载内容直接通过管道交给 shell。下载脚本后先固定来源、检查内容，再以 root 执行。</p><h2 id="环境配置" tabindex="-1">环境配置 <a class="header-anchor" href="#环境配置" aria-label="Permalink to “环境配置”">​</a></h2><p>从应用仓库的 <code>.env.example</code> 建立 <code>.env</code>，至少设置：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>JWT_SECRET=&lt;长随机值&gt;</span></span>
<span class="line"><span>POSTGRES_PASSWORD=&lt;独立数据库强密码&gt;</span></span>
<span class="line"><span>SENDCHANNEL_KEK_HEX=&lt;openssl rand -hex 32 生成的 64 位十六进制值&gt;</span></span>
<span class="line"><span>FRONTEND_URL=https://your-domain.com</span></span>
<span class="line"><span>APP_BASE_PATH=/app</span></span>
<span class="line"><span>MAIL_SERVER_HOSTNAME=mail.your-domain.com</span></span>
<span class="line"><span>SMTP_DOMAIN=your-domain.com</span></span>
<span class="line"><span>WEB_BIND=127.0.0.1:18080</span></span></code></pre></div><p><code>FRONTEND_URL</code> 只填站点根地址，不带 <code>/app</code>。使用宿主机 Nginx、宝塔或 1Panel 时把 Docker Web 入口绑定到回环地址。生产环境应启用 Secure Cookie。</p><p><code>SENDCHANNEL_KEK_HEX</code> 用来加密 SMTP、出站通道、对象存储、TLS、支付和图床密钥。首次生成后保持不变并单独备份；随意更换会使已保存密钥无法解密。</p><h2 id="首次启动" tabindex="-1">首次启动 <a class="header-anchor" href="#首次启动" aria-label="Permalink to “首次启动”">​</a></h2><p>在已经审查的代码提交上执行：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --quiet</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tail=200</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span></span></code></pre></div><p>后端启动时按编号执行尚未完成的迁移，当前序列到 <code>065</code>。迁移失败会停止启动；不要删除迁移记录、手工标记成功或用持续重启掩盖错误。</p><h2 id="创建管理员" tabindex="-1">创建管理员 <a class="header-anchor" href="#创建管理员" aria-label="Permalink to “创建管理员”">​</a></h2><p>管理员密码通过临时环境变量传给 seed，不写在命令参数或源码中：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">read</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;New administrator password: &quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ADMIN_PASSWORD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ADMIN_PASSWORD</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ADMIN_PASSWORD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /app/seed</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">unset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ADMIN_PASSWORD</span></span></code></pre></div><p>默认管理员用户名是 <code>admin</code>。密码至少 12 位，并包含小写、大写、数字和符号中的至少三类。若管理员已经存在，seed 保留原密码、权限和启用状态，不会自动重置或重新激活。</p><h2 id="dns-与端口" tabindex="-1">DNS 与端口 <a class="header-anchor" href="#dns-与端口" aria-label="Permalink to “DNS 与端口”">​</a></h2><p>典型 DNS：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>A      @       &lt;服务器 IP&gt;             可使用 Web 代理</span></span>
<span class="line"><span>A      www     &lt;服务器 IP&gt;             可使用 Web 代理</span></span>
<span class="line"><span>A      mail    &lt;服务器 IP&gt;             DNS only</span></span>
<span class="line"><span>MX     @       mail.example.com        优先级 10</span></span>
<span class="line"><span>TXT    @       v=spf1 mx ~all</span></span>
<span class="line"><span>TXT    _dmarc  v=DMARC1; p=none; ...</span></span></code></pre></div><p>公网按实际启用功能开放：</p><table tabindex="0"><thead><tr><th>端口</th><th>用途</th></tr></thead><tbody><tr><td>25</td><td>SMTP 入站收信</td></tr><tr><td>587</td><td>SMTP Submission，推荐 STARTTLS</td></tr><tr><td>993</td><td>IMAPS</td></tr><tr><td>995</td><td>POP3S</td></tr><tr><td>80</td><td>ACME 验证或跳转 HTTPS</td></tr><tr><td>443</td><td>Web HTTPS</td></tr></tbody></table><p>PostgreSQL 5432、Redis 6379、后端 8080 和本机反代 18080 不应直接暴露公网。</p><h2 id="宿主机反向代理" tabindex="-1">宿主机反向代理 <a class="header-anchor" href="#宿主机反向代理" aria-label="Permalink to “宿主机反向代理”">​</a></h2><p>外层代理必须覆盖访客提交的代理头：</p><div class="language-nginx"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Host $host;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Real-IP $remote_addr;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Forwarded-For $remote_addr;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Forwarded-Proto $scheme;</span></span></code></pre></div><p>项目内层 Nginx 只从可信直连代理接收单个已验证 IP，再写入后端专用头。登录、注册、Turnstile、审计和限速使用这个规范地址。不要把任意 <code>X-Forwarded-For</code> 链直接交给应用。</p><p>访问日志应记录路径而不记录完整查询参数、Cookie、OAuth code 或验证码。</p><h2 id="cloudflare" tabindex="-1">Cloudflare <a class="header-anchor" href="#cloudflare" aria-label="Permalink to “Cloudflare”">​</a></h2><ul><li>Web 根域和 <code>www</code> 可使用 Cloudflare 代理。</li><li><code>mail</code> 必须保持 DNS only。</li><li>优先使用 Full (strict)，源站证书覆盖所有 Web 主机名。</li><li>外层 Nginx 只信任 Cloudflare 官方 IP 段提供的 <code>CF-Connecting-IP</code>。</li><li>防火墙或虚拟主机阻止绕过 Cloudflare 直接访问 Web 源站。</li><li>若使用 Flexible，需要根据 <code>CF-Visitor</code> 向内层传递真实访客协议，避免重定向循环；同时在 Cloudflare 边缘强制 HTTPS。</li></ul><p><code>www</code> 和邮件 Web 主机应明确重定向到规范入口，不能落入服务器上的其他默认网站。</p><p>若 Turnstile 故障导致管理员也无法登录，可临时在环境中显式设置 <code>TURNSTILE_ENABLED=false</code> 并重启后端。该救援值会覆盖数据库配置；空值不会关闭保护。修复后移除覆盖值并再次重启。</p><h2 id="tls" tabindex="-1">TLS <a class="header-anchor" href="#tls" aria-label="Permalink to “TLS”">​</a></h2><p>网页与邮件协议都需要有效证书。邮件后端必须能读取证书链和私钥；续期后重新加载实际使用证书的进程。</p><p>分别验证：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s_client</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -connect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mail.example.com:587</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -starttls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smtp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -servername</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mail.example.com</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s_client</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -connect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mail.example.com:993</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -servername</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mail.example.com</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s_client</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -connect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mail.example.com:995</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -servername</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mail.example.com</span></span></code></pre></div><p>检查 SAN 主机名、签发链和到期时间。浏览器证书正确并不保证邮件端口也加载了新证书。</p><h2 id="注册认证邮件" tabindex="-1">注册认证邮件 <a class="header-anchor" href="#注册认证邮件" aria-label="Permalink to “注册认证邮件”">​</a></h2><p>后台的“系统 SMTP”用于注册、找回密码和找回邮箱验证，独立于用户业务邮件出站通道。完成 SMTP 测试后再开启邮箱验证。配置方法见 <a href="/nodemail-docs/admin/registration-smtp-turnstile">注册、SMTP 认证邮件与 Turnstile</a>。</p><h2 id="上线前" tabindex="-1">上线前 <a class="header-anchor" href="#上线前" aria-label="Permalink to “上线前”">​</a></h2><p>在生产数据副本完成迁移和写操作测试，再检查健康端点、用户/管理员接口、前端路由、收发信、附件、客户端协议、注册、找回密码、NodeLoc、Turnstile、订单回调和审计。正式环境的测试数据和临时容器完成后及时清理。</p>`,45)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};